#!/usr/bin/env python3
"""
Round 100b tiles patch (28 September 2026), beside round100b_culprits.py.

  scripts/public_harm.py    new: World Bank projects rated Category A or High
                            risk, at their own locations, and the IMF's fossil
                            fuel subsidies by country (subsidies/).
  scripts/fish_rivers.py    new: Grill et al. 2019's free-flowing rivers,
                            every reach, as the map's own tiles.
  scripts/fish_basins.py    new: Tedesco et al. 2017's freshwater fish, native,
                            introduced and endemic species per river basin.
  scripts/ftw_overview.py   new: Fields of The World counted per one-degree
                            square from its download files' footers.
  scripts/fur_farms.py      every Final Nail field kept whole (so its own row
                            can go); every Farm Transparency skin facility kept,
                            grouped by species; other Overpass servers tried.
  scripts/enforcement_sample.py  new, by hand: the columns and first rows of
                            Canada's, England's and the US EPA's registers.
  scripts/pe_probe.py       also reads the Bankrolling Extinction campaign page.

Whole files, written only where they differ. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/public_harm.py': '', 'scripts/fish_rivers.py': '', 'scripts/fish_basins.py': '', 'scripts/ftw_overview.py': '', 'scripts/fur_farms.py': '', 'scripts/enforcement_sample.py': '', 'scripts/pe_probe.py': ''}

changed = []
for path, b64 in FILES.items():
    p = pathlib.Path(path)
    new = base64.b64decode(b64)
    if not p.parent.exists():
        raise SystemExit(f"round100b: {p.parent} not found; run from the culprits-tiles-more root")
    if p.exists() and p.read_bytes() == new:
        continue
    p.write_bytes(new)
    changed.append(path)
print("round100b: " + (", ".join(changed) if changed else "nothing to change (already applied)"))
